SET LOCAL standard_conforming_strings = on;

SET LOCAL lock_timeout = '10s';

CREATE TEMP TABLE _refresh_school_051126 (code text PRIMARY KEY, university_data jsonb NOT NULL, offering_data jsonb NOT NULL) ON COMMIT DROP;


DO $guard$
BEGIN
    IF EXISTS (
        SELECT 1 FROM _refresh_school_051126 s
        LEFT JOIN app.universities u ON u.code = s.code
        LEFT JOIN app.university_offerings o ON o.university_id = u.id AND o.study_level = 'undergraduate'
        WHERE u.id IS NULL OR o.id IS NULL
    ) THEN
        RAISE EXCEPTION 'School dataset refresh requires the original 249 universities and undergraduate offerings; no records have been replaced.';
    END IF;
END $guard$;

WITH incoming AS (
    SELECT t.id, jsonb_populate_record(NULL::app.universities, to_jsonb(t) || s.university_data) AS row_data
    FROM _refresh_school_051126 s
    JOIN app.universities t ON t.code = s.code
)
UPDATE app.universities target
SET name = (incoming.row_data).name,
    city = (incoming.row_data).city,
    state = (incoming.row_data).state,
    website = (incoming.row_data).website,
    control = (incoming.row_data).control,
    acceptance_rate = (incoming.row_data).acceptance_rate,
    international_student_count = (incoming.row_data).international_student_count,
    is_ivy = (incoming.row_data).is_ivy,
    updated_at = CURRENT_TIMESTAMP
FROM incoming
WHERE target.id = incoming.id
  AND ROW(target.name, target.city, target.state, target.website, target.control, target.acceptance_rate, target.international_student_count, target.is_ivy) IS DISTINCT FROM ROW((incoming.row_data).name, (incoming.row_data).city, (incoming.row_data).state, (incoming.row_data).website, (incoming.row_data).control, (incoming.row_data).acceptance_rate, (incoming.row_data).international_student_count, (incoming.row_data).is_ivy);


WITH incoming AS (
    SELECT t.id, jsonb_populate_record(NULL::app.university_offerings, to_jsonb(t) || s.offering_data || CASE WHEN s.offering_data ? 'deadlines_json' THEN jsonb_build_object('deadlines_json', COALESCE(NULLIF(t.deadlines_json, 'null'::jsonb), '{}'::jsonb) || (s.offering_data->'deadlines_json')) ELSE '{}'::jsonb END) AS row_data
    FROM _refresh_school_051126 s
    JOIN app.universities u ON u.code = s.code JOIN app.university_offerings t ON t.university_id = u.id AND t.study_level = 'undergraduate'
)
UPDATE app.university_offerings target
SET academic_year = (incoming.row_data).academic_year,
    tuition_usd = (incoming.row_data).tuition_usd,
    living_usd = (incoming.row_data).living_usd,
    fees_usd = (incoming.row_data).fees_usd,
    other_expenses_usd = (incoming.row_data).other_expenses_usd,
    min_gpa4 = (incoming.row_data).min_gpa4,
    min_ielts = (incoming.row_data).min_ielts,
    min_toefl = (incoming.row_data).min_toefl,
    min_duolingo = (incoming.row_data).min_duolingo,
    avg_gpa4 = (incoming.row_data).avg_gpa4,
    sat25 = (incoming.row_data).sat25,
    sat75 = (incoming.row_data).sat75,
    act25 = (incoming.row_data).act25,
    act75 = (incoming.row_data).act75,
    sat_policy = (incoming.row_data).sat_policy,
    deadlines_json = (incoming.row_data).deadlines_json,
    c7_gpa_importance = (incoming.row_data).c7_gpa_importance,
    c7_test_importance = (incoming.row_data).c7_test_importance,
    c7_ec_importance = (incoming.row_data).c7_ec_importance,
    applicants_total = (incoming.row_data).applicants_total,
    admitted_total = (incoming.row_data).admitted_total,
    intl_applicants = (incoming.row_data).intl_applicants,
    intl_admitted = (incoming.row_data).intl_admitted,
    intl_acceptance_rate = (incoming.row_data).intl_acceptance_rate,
    intl_aid_policy = (incoming.row_data).intl_aid_policy,
    intl_aid_avg_usd = (incoming.row_data).intl_aid_avg_usd,
    intl_aid_recipients = (incoming.row_data).intl_aid_recipients,
    sat_submit_pct = (incoming.row_data).sat_submit_pct,
    gpa_submit_pct = (incoming.row_data).gpa_submit_pct,
    gpa_pct_4_0 = (incoming.row_data).gpa_pct_4_0,
    gpa_pct_375_399 = (incoming.row_data).gpa_pct_375_399,
    gpa_pct_350_374 = (incoming.row_data).gpa_pct_350_374,
    gpa_pct_325_349 = (incoming.row_data).gpa_pct_325_349,
    gpa_pct_300_324 = (incoming.row_data).gpa_pct_300_324,
    gpa_pct_250_299 = (incoming.row_data).gpa_pct_250_299,
    gpa_pct_below_250 = (incoming.row_data).gpa_pct_below_250,
    retention_rate_1yr = (incoming.row_data).retention_rate_1yr,
    grad_rate_6yr = (incoming.row_data).grad_rate_6yr,
    updated_at = CURRENT_TIMESTAMP
FROM incoming
WHERE target.id = incoming.id
  AND ROW(target.academic_year, target.tuition_usd, target.living_usd, target.fees_usd, target.other_expenses_usd, target.min_gpa4, target.min_ielts, target.min_toefl, target.min_duolingo, target.avg_gpa4, target.sat25, target.sat75, target.act25, target.act75, target.sat_policy, target.deadlines_json, target.c7_gpa_importance, target.c7_test_importance, target.c7_ec_importance, target.applicants_total, target.admitted_total, target.intl_applicants, target.intl_admitted, target.intl_acceptance_rate, target.intl_aid_policy, target.intl_aid_avg_usd, target.intl_aid_recipients, target.sat_submit_pct, target.gpa_submit_pct, target.gpa_pct_4_0, target.gpa_pct_375_399, target.gpa_pct_350_374, target.gpa_pct_325_349, target.gpa_pct_300_324, target.gpa_pct_250_299, target.gpa_pct_below_250, target.retention_rate_1yr, target.grad_rate_6yr) IS DISTINCT FROM ROW((incoming.row_data).academic_year, (incoming.row_data).tuition_usd, (incoming.row_data).living_usd, (incoming.row_data).fees_usd, (incoming.row_data).other_expenses_usd, (incoming.row_data).min_gpa4, (incoming.row_data).min_ielts, (incoming.row_data).min_toefl, (incoming.row_data).min_duolingo, (incoming.row_data).avg_gpa4, (incoming.row_data).sat25, (incoming.row_data).sat75, (incoming.row_data).act25, (incoming.row_data).act75, (incoming.row_data).sat_policy, (incoming.row_data).deadlines_json, (incoming.row_data).c7_gpa_importance, (incoming.row_data).c7_test_importance, (incoming.row_data).c7_ec_importance, (incoming.row_data).applicants_total, (incoming.row_data).admitted_total, (incoming.row_data).intl_applicants, (incoming.row_data).intl_admitted, (incoming.row_data).intl_acceptance_rate, (incoming.row_data).intl_aid_policy, (incoming.row_data).intl_aid_avg_usd, (incoming.row_data).intl_aid_recipients, (incoming.row_data).sat_submit_pct, (incoming.row_data).gpa_submit_pct, (incoming.row_data).gpa_pct_4_0, (incoming.row_data).gpa_pct_375_399, (incoming.row_data).gpa_pct_350_374, (incoming.row_data).gpa_pct_325_349, (incoming.row_data).gpa_pct_300_324, (incoming.row_data).gpa_pct_250_299, (incoming.row_data).gpa_pct_below_250, (incoming.row_data).retention_rate_1yr, (incoming.row_data).grad_rate_6yr);


CREATE TEMP TABLE _refresh_evidence_051126 (id uuid PRIMARY KEY, code text NOT NULL, field_name text NOT NULL, field_value text, source_url text, source_section text, detail jsonb NOT NULL, status text NOT NULL) ON COMMIT DROP;




































































































































SELECT e.id, u.id, e.field_name, e.field_value, e.source_url, e.source_section, e.detail::text,
       'dataset_v2 0255_051126', e.status, CURRENT_TIMESTAMP
FROM _refresh_evidence_051126 e
JOIN app.universities u ON u.code = e.code
ON CONFLICT (id) DO NOTHING;

VALUES ('70c69317-908b-5dec-a054-6860b9730519', 'USAS-2004-dataset-0255-051126', 'usdss_dataset_0255_051126.xlsx', 'mixed; see field_evidence',
        13040, 4887, 8153, 'dataset_v2 import', 'imported_with_flags', CURRENT_TIMESTAMP)
ON CONFLICT (id) DO NOTHING;

DROP TABLE _refresh_evidence_051126;
